import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { firstMajorInMing, parseV4Record, readV4Records } from '../scripts/compare-v4';

// This metadata was read from the checksum-verified published year-1990 release, not generated by a model.
const actualReleaseRow = { k: '1990-01-01-0-male', y: 1990, m: 1, d: 1, h: 0, g: 'male', ms: '天府' };

test('v4 release parser checks schema, actual date and key agreement', () => {
  assert.deepEqual(parseV4Record({ ...actualReleaseRow, c: { overview: 'ignored interpretation' } }), actualReleaseRow);
  assert.throws(() => parseV4Record({ ...actualReleaseRow, h: 12 }), /branch index/);
  assert.throws(() => parseV4Record({ ...actualReleaseRow, d: 30, m: 2 }), /invalid Gregorian date/);
  assert.throws(() => parseV4Record({ ...actualReleaseRow, h: 1 }), /key does not match/);
  assert.throws(() => parseV4Record({ ...actualReleaseRow, ms: 'unknown' }), /known major-star/);
  assert.equal(parseV4Record({ ...actualReleaseRow, ms: null }).ms, null);
});

test('Mệnh lookup uses branch identity and preserves the meaning of null', () => {
  const other = { branch: 3, stem: 0, name: '财帛', stars: [{ name: '天机', type: 'major' as const }] };
  const ming = { branch: 7, stem: 0, name: '命宫', stars: [{ name: '文昌', type: 'minor' as const }, { name: '天府', type: 'major' as const }] };
  assert.equal(firstMajorInMing({ mingGongBranch: 7, palaces: [other, ming] }), '天府');
  assert.equal(firstMajorInMing({ mingGongBranch: 7, palaces: [{ ...ming, stars: [] }] }), null);
  assert.throws(() => firstMajorInMing({ mingGongBranch: 0, palaces: [other, ming] }), /Mệnh palace/);
});

test('streaming JSONL accepts BOM/CRLF and rejects malformed/truncated input', async () => {
  const folder = mkdtempSync(join(tmpdir(), 'tuvi-dataset-'));
  const file = join(folder, 'sample.jsonl');
  try {
    writeFileSync(file, `\uFEFF${JSON.stringify(actualReleaseRow)}\r\n${JSON.stringify({ ...actualReleaseRow, k: '1990-01-01-0-female', g: 'female' })}\r\n`, 'utf8');
    const rows = [];
    for await (const row of readV4Records(file)) rows.push(row);
    assert.equal(rows.length, 2);
    assert.equal(rows[0].ms, '天府');
    writeFileSync(file, `${JSON.stringify(actualReleaseRow)}\n{"k":`, 'utf8');
    await assert.rejects(async () => { for await (const row of readV4Records(file)) void row; }, /Invalid JSON at line 2/);
  } finally { rmSync(folder, { recursive: true, force: true }); }
});
